from taf.ul.ettf.msg_capture.expectations import ExpectationsManager
from taf.ul.ettf.msg_capture.expectation_builders.detailed import MessageDetail
from taf.ul.ettf.pdml_parser.parser import Enum
from taf.ul.ettf.ta_matchers.matchers import Any, Omit
from taf.ul.ettf.typed.typed import typed


e_scs = {
    'kHz15': 0,
    'kHz30': 1,
    'kHz120': 2,
    'kHz240': 3
}


def releaseCause(cause, value):
    return Any({'releaseCause': Enum(cause, value)})


releaseCauses = {
    'inactivity': releaseCause('inactivity', 0),
    'other': releaseCause('other', 1),
}


class redirect(ExpectationsManager):

    @typed(cause=str)
    def with_release_cause(self, cause):
        self.append_expectation(MessageDetail('rrcConnectionRelease-r8', releaseCauses[cause]))

    @typed(freq=int, subcarrier_spacing=str)
    def with_nr_redirect_carrier_info(self, freq, subcarrier_spacing):
        redirect_carrier = Any({
            'redirectedCarrierInfo': Any({
                'nr-r15': Any({
                    'carrierFreq-r15': freq,
                    'subcarrierSpacingSSB-r15': Enum(subcarrier_spacing, e_scs[subcarrier_spacing]),
                    'smtc-r15': Omit()
                })
            })
        })
        self.append_expectation(MessageDetail('rrcConnectionRelease-r8', redirect_carrier))
